import{_ as r,o as t,c as o,a2 as l}from"./chunks/framework.BV21bweQ.js";const g=JSON.parse('{"title":"底层设定","description":"","frontmatter":{},"headers":[],"relativePath":"底层/index.md","filePath":"底层/index.md","lastUpdated":1787066340000}'),e={name:"底层/index.md"};function i(n,a,s,h,d,u){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="底层设定" tabindex="-1">底层设定 <a class="header-anchor" href="#底层设定" aria-label="Permalink to &quot;底层设定&quot;">​</a></h1><h2 id="概念诠释" tabindex="-1">概念诠释 <a class="header-anchor" href="#概念诠释" aria-label="Permalink to &quot;概念诠释&quot;">​</a></h2><p>底层设定是神造物世界观中的<strong>基础元规则层面</strong>，描述了世界的最根本结构和运作原理。这一层面构成了整个世界观的基础架构，中层和表层设定都建立在这些底层规则之上。底层设定揭示了世界的本质、起源和基本运行机制，是理解神造物世界观复杂性的关键。</p><p>底层设定可以被理解为&quot;世界的源代码&quot;——定义了世界的核心规则、约束和可能性边界，是世界观中最基础、最本质的部分。</p><h2 id="定位与特点" tabindex="-1">定位与特点 <a class="header-anchor" href="#定位与特点" aria-label="Permalink to &quot;定位与特点&quot;">​</a></h2><p><strong>核心定位：</strong></p><ul><li><strong>基础架构</strong>：为整个世界观提供基础规则和原理支持</li><li><strong>元规则层面</strong>：描述的是世界的元规则，而非具体现象或事件</li><li><strong>影响全域</strong>：底层设定的规则影响所有层面，从宇宙诞生到叙事逻辑</li></ul><p><strong>主要特点：</strong></p><ul><li><strong>抽象性</strong>：概念较为抽象，涉及世界本质和基本原理</li><li><strong>普适性</strong>：规则适用于世界观中的所有存在和现象</li><li><strong>不变性</strong>：底层设定通常被认为是不可改变的世界基础</li><li><strong>系统性</strong>：各概念之间存在紧密的逻辑联系</li></ul><h2 id="核心内容领域" tabindex="-1">核心内容领域 <a class="header-anchor" href="#核心内容领域" aria-label="Permalink to &quot;核心内容领域&quot;">​</a></h2><p>底层设定主要涵盖以下几个核心领域：</p><h3 id="_1-基底层与现实世界" tabindex="-1">1. 基底层与现实世界 <a class="header-anchor" href="#_1-基底层与现实世界" aria-label="Permalink to &quot;1. 基底层与现实世界&quot;">​</a></h3><p>描述世界的起源、结构与基本运作原理，包括基底层概念、现实世界诞生过程、地球作为薄弱点的定位等</p><blockquote><p><strong>详细内容参见</strong>：<a href="./规则/基底层与现实世界">基底层与现实世界</a></p></blockquote><h3 id="_2-神权体系" tabindex="-1">2. 神权体系 <a class="header-anchor" href="#_2-神权体系" aria-label="Permalink to &quot;2. 神权体系&quot;">​</a></h3><p>定义创造、变化、毁灭三大神权的本质、规则与运作机制，包括神权分类、使用代价、宏愿机制、上下位划分等</p><blockquote><p><strong>详细内容参见</strong>：<a href="./规则/神权体系">神权体系</a></p></blockquote><h3 id="_3-叙事与玩家" tabindex="-1">3. 叙事与玩家 <a class="header-anchor" href="#_3-叙事与玩家" aria-label="Permalink to &quot;3. 叙事与玩家&quot;">​</a></h3><p>描述世界运行的元规则层面，包括叙事逻辑特性、玩家特殊性、时间线规则等</p><blockquote><p><strong>详细内容参见</strong>：<a href="./规则/叙事与玩家">叙事与玩家</a></p></blockquote><h3 id="_4-元层面人物" tabindex="-1">4. 元层面人物 <a class="header-anchor" href="#_4-元层面人物" aria-label="Permalink to &quot;4. 元层面人物&quot;">​</a></h3><p>与底层规则直接相关的存在：创造现实的初代创造神、补完规则的初代变化神、删除一切的上位毁灭神（小白狼），以及身处概念性人类与游戏真相核心的林月。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./人物/">元层面人物</a></p></blockquote><h2 id="与世界观其他层面的关系" tabindex="-1">与世界观其他层面的关系 <a class="header-anchor" href="#与世界观其他层面的关系" aria-label="Permalink to &quot;与世界观其他层面的关系&quot;">​</a></h2><h3 id="与中层设定的关系" tabindex="-1">与中层设定的关系 <a class="header-anchor" href="#与中层设定的关系" aria-label="Permalink to &quot;与中层设定的关系&quot;">​</a></h3><ul><li><strong>基础与体现</strong>：底层设定是中层的理论基础，中层是底层的具体应用和体现</li><li><strong>抽象与具体</strong>：底层是抽象规则，中层是具体实现和真相揭示</li><li><strong>原理与现象</strong>：底层解释原理，中层解释现象背后的真相</li></ul><h3 id="与表层设定的关系" tabindex="-1">与表层设定的关系 <a class="header-anchor" href="#与表层设定的关系" aria-label="Permalink to &quot;与表层设定的关系&quot;">​</a></h3><ul><li><strong>规则与表象</strong>：底层设定定义了表层世界运行的规则</li><li><strong>本质与现象</strong>：底层是世界本质，表层是现象表现</li><li><strong>不可认知性</strong>：福瑞种族无法直接认知底层设定内容</li></ul><h2 id="阅读建议" tabindex="-1">阅读建议 <a class="header-anchor" href="#阅读建议" aria-label="Permalink to &quot;阅读建议&quot;">​</a></h2><ol><li><strong>先理解概念</strong>：底层设定概念较为抽象，建议先理解基本概念框架</li><li><strong>交叉参考</strong>：三个底层设定文档之间存在紧密逻辑联系，建议交叉阅读</li><li><strong>理解层次</strong>：认识到这是世界的最基础规则，中层和表层都建立于此</li><li><strong>保持距离</strong>：这些内容不应直接出现在表层叙事中，是&quot;世界背后的代码&quot;</li></ol><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./规则/基底层与现实世界">基底层与现实世界</a></li><li><a href="./规则/神权体系">神权体系</a></li><li><a href="./规则/叙事与玩家">叙事与玩家</a></li><li><a href="./人物/">元层面人物</a></li><li><a href="./../中层/" class="layer-link" data-layer="中层">中层设定</a></li><li><a href="./../表层/" class="layer-link" data-layer="表层">表层设定</a></li></ul><hr>',34)])])}const p=r(e,[["render",i]]);export{g as __pageData,p as default};
